mapper.select:
SELECT EXISTS (
    SELECT 1 FROM (
        SELECT draft_json AS content FROM public.nocode_report_dataset WHERE id=#{id} AND deleted=0
        UNION ALL SELECT definition_json FROM public.nocode_report_dataset_version WHERE dataset_id=#{id} AND deleted=0
    ) definitions WHERE content #>> '{source,root,objectId}'=#{object}
        OR EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(content #> '{source,relations}','[]'::jsonb)) relation WHERE relation #>> '{target,objectId}'=#{object})
)
